import { useContext, useEffect, useState } from 'react';
import AuthContext from '../context/AuthContext';
import axios from 'axios';

function Dashboard() {
  const { user } = useContext(AuthContext);
  const [resumes, setResumes] = useState([]);

  useEffect(() => {
    async function load() {
      try {
        const res = await axios.get('http://localhost:5001/api/resume/my', { withCredentials: true });
        setResumes(res.data.data);
      } catch (err) {
        console.error(err);
      }
    }
    if (user) load();
  }, [user]);

  if (!user) return <div style={{ padding: 20 }}>Please login to view your dashboard</div>;

  return (
    <div className="page mt-6">
      <div className="container">
        <header className="mb-8">
          <h2 className="text-2xl font-black mb-1">{user.name || user.email}'s Dashboard</h2>
          <p className="muted">Track your applications and match results with AI-driven insights.</p>
        </header>

        <div className="max-w-4xl mx-auto">
          {resumes.length === 0 ? (
            <div className="card text-center py-12">
              <p className="muted">No resumes uploaded yet. Start by uploading your profile to see insights.</p>
              <button className="btn btn-primary mt-4" onClick={() => window.location.href = '/upload'}>Upload Resume</button>
            </div>
          ) : (
            <div className="flex flex-col gap-6">
              {resumes.map(r => (
                <div key={r._id} className="card hover-shadow border-l-4 transition-all" style={{ borderLeftColor: r.score >= 70 ? 'var(--success)' : (r.score >= 40 ? '#f59e0b' : 'var(--danger)') }}>
                  <div className="flex flex-col md:flex-row justify-between gap-6">
                    <div className="flex-1">
                      <div className="flex items-center flex-wrap gap-2 mb-4">
                        <span className={`badge ${r.score >= 70 ? 'bg-success' : (r.score >= 40 ? 'bg-info' : 'bg-danger')}`}>
                          Match Score: {Math.round(r.score || 0)}%
                        </span>
                        <span className="badge bg-secondary">Status: {r.interviewStatus}</span>
                        {r.jobId?.title && <span className="badge bg-slate-100 text-slate-700">Role: {r.jobId.title}</span>}
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="bg-slate-100/50 p-4 rounded-xl border border-slate-100">
                          <span className="block text-[10px] muted uppercase font-black mb-2">Matched Skills</span>
                          <div className="flex flex-wrap gap-1">
                            {(r.matchedSkills || r.skills || []).map((s, i) => (
                              <span key={i} className="badge bg-white shadow-sm border border-slate-200">{s}</span>
                            ))}
                          </div>
                        </div>
                        <div className="bg-slate-100/50 p-4 rounded-xl border border-slate-100">
                          <span className="block text-[10px] muted uppercase font-black mb-2">Missing Skills</span>
                          <div className="flex flex-wrap gap-1">
                            {(r.missingSkills || []).length > 0 ? (
                              (r.missingSkills || []).map((s, i) => (
                                <span key={i} className="badge bg-white shadow-sm border border-slate-200 text-rose-600">{s}</span>
                              ))
                            ) : (
                              <span className="text-sm muted">None identified</span>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="flex flex-col justify-center gap-3" style={{ minWidth: '160px' }}>
                      <div className="text-center">
                        <p className="muted text-[10px] font-bold uppercase mb-1">Applied Date</p>
                        <p className="text-sm font-bold">{r.createdAt ? new Date(r.createdAt).toLocaleDateString() : 'N/A'}</p>
                      </div>
                      <button className="btn btn-ghost w-full">View Full Analysis</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
